import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'

/** Joins class names and lets the last conflicting Tailwind utility win. */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import { readCssVar } from './tokens-runtime'

/**
 * The JavaScript half of M7 (motion.css, "M7 exits"): the exits whose second act is layout, which
 * a CSS keyframe on the leaving element cannot do on its own.
 *
 * - `exitTag`: the tag fades and shrinks in place; once it is gone, its neighbours slide from
 *   where they stood into the space it left (`slideIntoPlace`, a FLIP run by each neighbour).
 * - `exitAlert`: the alert fades, then its height collapses so the content below rises into its
 *   place instead of jumping.
 *
 * Both run on the Web Animations API and read the motion tokens at the moment they run, so a
 * changed token changes them too. Where nothing can animate -- reduced motion, or an environment
 * with no `Element.animate` (jsdom) -- `onDone` runs at once, so a dismiss never waits on a
 * motion that will not play.
 */

export function prefersReducedMotion(): boolean {
  return (
    typeof window.matchMedia === 'function' &&
    window.matchMedia('(prefers-reduced-motion: reduce)').matches
  )
}

function canAnimate(el: HTMLElement | null): el is HTMLElement {
  return !!el && typeof el.animate === 'function' && !prefersReducedMotion()
}

function ms(token: string, fallback: number): number {
  const value = Number.parseFloat(readCssVar(token))
  return Number.isFinite(value) ? value : fallback
}

function ease(token: string, fallback: string): string {
  return readCssVar(token) || fallback
}

const SNAP = 'cubic-bezier(0.2, 0.8, 0.2, 1)'
const ACCELERATE = 'cubic-bezier(0.4, 0, 1, 1)'

/** Where each sibling stood when an exit finished, per parent. Read once by `slideIntoPlace` in
 *  the render that removes the leaving element; anything older than `STALE_MS` is ignored, so a
 *  snapshot that was never consumed (the parent kept the element) cannot fire on a later,
 *  unrelated render. */
const snapshots = new WeakMap<Element, { at: number; positions: Map<Element, { x: number; y: number }> }>()
const STALE_MS = 1000

function snapshotSiblings(el: HTMLElement) {
  const parent = el.parentElement
  if (!parent) return
  const positions = new Map<Element, { x: number; y: number }>()
  for (const child of Array.from(parent.children)) {
    if (child !== el && child instanceof HTMLElement) {
      positions.set(child, { x: child.offsetLeft, y: child.offsetTop })
    }
  }
  snapshots.set(parent, { at: performance.now(), positions })
}

/**
 * FLIP for a sibling of an element that just left: called from the sibling's own layout effect,
 * after the render that removed the leaver. If the sibling moved, it is put back where it stood and
 * slid to where it now is. Offsets, not client rects, so a page scroll in between is not a move.
 */
export function slideIntoPlace(el: HTMLElement | null) {
  const parent = el?.parentElement
  if (!el || !parent) return
  const snapshot = snapshots.get(parent)
  const from = snapshot?.positions.get(el)
  if (!snapshot || !from) return
  snapshot.positions.delete(el)
  if (performance.now() - snapshot.at > STALE_MS || !canAnimate(el)) return
  const dx = from.x - el.offsetLeft
  const dy = from.y - el.offsetTop
  if (dx === 0 && dy === 0) return
  el.animate([{ transform: `translate(${dx}px, ${dy}px)` }, { transform: 'none' }], {
    duration: ms('--duration-base', 180),
    easing: ease('--ease-snap', SNAP),
  })
}

/** Holds the final frame until the parent removes the element. If the parent keeps it (a
 *  controlled list that ignored the dismiss), the element comes back on the next frame rather than
 *  staying invisible and still focusable. */
function releaseIfKept(el: HTMLElement, animations: Animation[]) {
  requestAnimationFrame(() => {
    if (el.isConnected) animations.forEach(animation => animation.cancel())
  })
}

export function exitTag(el: HTMLElement | null, onDone: () => void) {
  if (!canAnimate(el)) return onDone()
  const fade = el.animate([{ opacity: 1, transform: 'scale(1)' }, { opacity: 0, transform: 'scale(0.85)' }], {
    duration: ms('--duration-fast', 120),
    easing: ease('--ease-accelerate', ACCELERATE),
    fill: 'forwards',
  })
  fade.onfinish = () => {
    snapshotSiblings(el)
    onDone()
    releaseIfKept(el, [fade])
  }
}

export function exitAlert(el: HTMLElement | null, onDone: () => void) {
  if (!canAnimate(el)) return onDone()
  const fade = el.animate([{ opacity: 1, transform: 'none' }, { opacity: 0, transform: 'translateY(-4px)' }], {
    duration: ms('--duration-fast', 120),
    easing: ease('--ease-accelerate', ACCELERATE),
    fill: 'forwards',
  })
  fade.onfinish = () => {
    const style = getComputedStyle(el)
    el.style.overflow = 'hidden'
    const collapse = el.animate(
      [
        {
          height: `${el.offsetHeight}px`,
          paddingTop: style.paddingTop,
          paddingBottom: style.paddingBottom,
          marginTop: style.marginTop,
          marginBottom: style.marginBottom,
          borderTopWidth: style.borderTopWidth,
          borderBottomWidth: style.borderBottomWidth,
        },
        {
          height: '0px',
          paddingTop: '0px',
          paddingBottom: '0px',
          marginTop: '0px',
          marginBottom: '0px',
          borderTopWidth: '0px',
          borderBottomWidth: '0px',
        },
      ],
      { duration: ms('--duration-base', 180), easing: ease('--ease-snap', SNAP), fill: 'forwards' }
    )
    collapse.onfinish = () => {
      onDone()
      requestAnimationFrame(() => {
        if (el.isConnected) {
          el.style.overflow = ''
          fade.cancel()
          collapse.cancel()
        }
      })
    }
  }
}

import { useState } from 'react'

/** Each field's current error message. A field with no entry has no error. */
export type FieldErrors<F extends string> = Partial<Record<F, string>>

/** The message for a value, or undefined when the value is fine. */
export type Validate<F extends string> = (field: F, value: string) => string | undefined

function withMessage<F extends string>(
  errors: FieldErrors<F>,
  field: F,
  message: string | undefined
): FieldErrors<F> {
  if (errors[field] === message) return errors
  const next = { ...errors }
  if (message === undefined) delete next[field]
  else next[field] = message
  return next
}

export function hasErrors<F extends string>(errors: FieldErrors<F>): boolean {
  return Object.values(errors).some(message => message !== undefined)
}

/** The errors in `order`, each with the id of the control an ErrorSummary entry should focus. */
export function summarize<F extends string>(
  errors: FieldErrors<F>,
  order: readonly F[],
  idOf: (field: F) => string
): { fieldId: string; message: string }[] {
  return order.flatMap(field => {
    const message = errors[field]
    return message === undefined ? [] : [{ fieldId: idOf(field), message }]
  })
}

/** What `useFieldErrors` returns. Written out, not inferred, so the generated helpers page prints it. */
export type FieldErrorsApi<F extends string> = {
  /** Each field's current error, for `FormField`'s `error` and for `summarize`. */
  errors: FieldErrors<F>
  /** Call from the control's onBlur with its current value and `event.relatedTarget`, where focus
   *  is going. A blur caused by pressing a submit button shows nothing: submit validates every
   *  field. */
  blur: (field: F, value: string, to?: EventTarget | null) => void
  /** Call from the control's onChange with its new value. */
  change: (field: F, value: string) => void
  /** Call on submit with every field and a way to read its value; returns the errors found. */
  validateAll: (fields: readonly F[], valueOf: (field: F) => string) => FieldErrors<F>
  /** Replace every error, with a server's or with `{}`. */
  replace: (next: FieldErrors<F>) => void
}

/** A submit button being pressed by the pointer right now. `:active` is set on pointer down,
 *  before the field blurs; a Tab onto the button never sets it, so keyboard users still hear the
 *  error on the way past, where there is no click to miss. */
function isSubmitPress(target: EventTarget | null | undefined): boolean {
  return (
    (target instanceof HTMLButtonElement || target instanceof HTMLInputElement) &&
    target.type === 'submit' &&
    target.matches(':active')
  )
}

/**
 * When a form's field errors may appear, change or clear, in one place (SC 3.3.1, and the rule
 * this system's forms share: never on a keystroke).
 *
 * - `blur`: show whatever is wrong with the value now, or clear the error when nothing is. Not
 *   when the pointer is pressing a submit button: the error line would push the button down
 *   under it mid-click, the click would miss, and submit validates every field anyway.
 * - `change`: never raises an error. Clears one as soon as its message no longer describes the
 *   value, so a stale "required" does not sit under a field that has text in it; the next blur
 *   says what, if anything, is wrong instead.
 * - `validateAll`: on submit, every given field at once, replacing what was shown. Returns what it
 *   found, so the caller can decide whether to submit.
 * - `replace`: errors from elsewhere (a server), or none.
 */
export function useFieldErrors<F extends string>(validate: Validate<F>): FieldErrorsApi<F> {
  const [errors, setErrors] = useState<FieldErrors<F>>({})
  return {
    errors,
    blur: (field: F, value: string, to?: EventTarget | null) => {
      if (isSubmitPress(to)) return
      setErrors(current => withMessage(current, field, validate(field, value)))
    },
    change: (field: F, value: string) =>
      setErrors(current => {
        const shown = current[field]
        return shown !== undefined && validate(field, value) !== shown ? withMessage(current, field, undefined) : current
      }),
    validateAll: (fields: readonly F[], valueOf: (field: F) => string): FieldErrors<F> => {
      const found: FieldErrors<F> = {}
      for (const field of fields) {
        const message = validate(field, valueOf(field))
        if (message !== undefined) found[field] = message
      }
      setErrors(found)
      return found
    },
    replace: (next: FieldErrors<F>) => setErrors(next),
  }
}

/** The currency's own decimal count (JPY has none, KWD has three), read from a throwaway
 *  formatter rather than hard-coded, so `formatMoney` and `formatMoneyCompact` convert a minor
 *  unit to a major one the same way regardless of which currency this call happens to be for. */
function minorUnitDigits(currency: string, locale: string): number {
  const formatter = new Intl.NumberFormat(locale, { style: 'currency', currency })
  // TypeScript's own lib types this optional (some Intl.ResolvedNumberFormatOptions fields are
  // style-dependent); for `style: 'currency'` it is always set, to the currency's own decimal
  // count, so `2` here is a type-only fallback, never a real one.
  return formatter.resolvedOptions().maximumFractionDigits ?? 2
}

/** Formats an amount held in the currency's own minor unit -- cents for EUR, fils for KWD, whole
 *  yen for JPY, which has none. Amounts are integers everywhere else in this system, so a sum of
 *  prices never picks up floating-point error; this is the one place they become text. A
 *  non-integer amount is rounded to the nearest whole minor unit rather than thrown on: a caller
 *  passing one is a bug upstream, not a reason to crash the page. */
export function formatMoney(
  minorUnits: number,
  { currency = 'EUR', locale = 'en-IE' }: { currency?: string; locale?: string } = {}
): string {
  const digits = minorUnitDigits(currency, locale)
  return new Intl.NumberFormat(locale, { style: 'currency', currency }).format(Math.round(minorUnits) / 10 ** digits)
}

/** The same conversion as `formatMoney`, abbreviated for a tight space -- a chart's y-axis tick,
 *  never a table cell or a total someone is meant to read exactly. Intl's own `notation:
 *  'compact'` only abbreviates once the value reaches four digits, so a typical monthly total
 *  under 1,000 reads as plain, un-rounded euros with no decimals ("€600"); above that it reads
 *  "€1.2K" rather than clipping the panel's fixed-width axis with "€1,200.00". */
export function formatMoneyCompact(
  minorUnits: number,
  { currency = 'EUR', locale = 'en-IE' }: { currency?: string; locale?: string } = {}
): string {
  const digits = minorUnitDigits(currency, locale)
  return new Intl.NumberFormat(locale, {
    style: 'currency',
    currency,
    notation: 'compact',
    maximumFractionDigits: 0,
  }).format(Math.round(minorUnits) / 10 ** digits)
}

import { useCallback, type Ref, type RefCallback } from 'react'

/** Writes `node` into one ref, whichever kind it is. */
export function assignRef<T>(ref: Ref<T> | undefined, node: T | null): void {
  if (typeof ref === 'function') ref(node)
  else if (ref) (ref as { current: T | null }).current = node
}

/**
 * One ref callback that feeds every ref it is given: a component's own (for focus management) and
 * the caller's. Its identity is stable while the refs are. React re-runs a ref callback whose
 * identity changes, detaching with null and reattaching with the node, so an inline
 * `node => { ... }` does that on every render. The refs are the dependency list, so the number of
 * refs passed must not change between renders of one component, the rule every hook's deps follow.
 *
 * Returns a cleanup, so React 19 detaches through it rather than by calling this callback again
 * with `null`. Each ref's own cleanup runs on detach: a callback ref's returned cleanup, if it gave
 * one; otherwise that callback called with `null`. An object ref's cleanup clears `.current`.
 */
export function useMergedRefs<T>(...refs: Array<Ref<T> | undefined>): RefCallback<T> {
  return useCallback((node: T | null) => {
    const cleanups = refs.map(ref => {
      if (typeof ref === 'function') {
        const cleanup = ref(node)
        return typeof cleanup === 'function' ? cleanup : () => ref(null)
      }
      if (ref) {
        ref.current = node
        return () => {
          ref.current = null
        }
      }
      return undefined
    })
    return () => {
      for (const cleanup of cleanups) cleanup?.()
    }
  }, refs)
}

import type { ReactNode } from 'react'

/** What an organism hands to its `renderLink` prop for each link it draws. */
export type LinkRenderProps = {
  href: string
  className: string
  children: ReactNode
  'aria-current'?: 'page'
  onClick?: () => void
}

/**
 * The default `renderLink`: a plain anchor. An app with a router passes its own link component
 * instead, mapping `href` to that component's prop, e.g. for React Router:
 * `renderLink={({ href, ...rest }) => <RouterLink to={href} {...rest} />}`. Whatever replaces the
 * anchor must still pass `className`, `aria-current` and `onClick` through to the rendered
 * element: the organism computes each one (the resting/current styling, the current-page state,
 * and, inside a menu sheet, the close-on-choose handler) and relies on it landing on the DOM node.
 */
export function renderAnchor(props: LinkRenderProps): ReactNode {
  return <a {...props} />
}

import { useEffect, useState } from 'react'
import { prefersReducedMotion } from './exit'

export type StreamedTextOptions = {
  /** Words revealed per second. @default 14 */
  speed?: number
  /** Starts the reveal; set it back to false and the text is empty again. @default true */
  active?: boolean
}

export type StreamedText = {
  /** What has arrived so far. */
  text: string
  /** Still arriving: pass it to ChatMessage's `streaming`. */
  streaming: boolean
  /** Everything has arrived, or the reveal was stopped. */
  done: boolean
  /** Stopped before the end, by `stop()`. */
  stopped: boolean
  /** Freezes the text where it is, the way a Stop button ends a real stream. */
  stop: () => void
}

/**
 * A scripted reply for a demo or a docs example: reveals `text` a word at a time while `active`, so
 * a ChatThread can be shown streaming without a model behind it. Changing `text` or turning
 * `active` on again starts over.
 *
 * Under `prefers-reduced-motion` the whole text arrives at once: words appearing one by one are
 * motion, and a reader who asked for less of it gets the reply the moment it exists.
 */
export function useStreamedText(text: string, { speed = 14, active = true }: StreamedTextOptions = {}): StreamedText {
  const words = text.split(/(?<=\s)/)
  const source = `${active}\u0000${text}`
  // Reset during render when the source changes, rather than in an effect, so no frame ever shows
  // the previous reply's text under the new one.
  const [state, setState] = useState({ source, count: 0, stopped: false })
  if (state.source !== source) setState({ source, count: 0, stopped: false })
  const current = state.source === source ? state : { source, count: 0, stopped: false }

  const total = words.length
  const running = active && !current.stopped && current.count < total

  useEffect(() => {
    if (!running) return
    if (prefersReducedMotion()) {
      setState(value => (value.source === source ? { ...value, count: total } : value))
      return
    }
    const timer = window.setInterval(() => {
      setState(value => (value.source === source ? { ...value, count: Math.min(total, value.count + 1) } : value))
    }, 1000 / speed)
    return () => window.clearInterval(timer)
  }, [running, source, speed, total])

  return {
    text: active ? words.slice(0, current.count).join('') : '',
    streaming: running,
    done: active && (current.stopped || current.count >= total),
    stopped: current.stopped,
    stop: () => setState(value => (value.source === source ? { ...value, stopped: true } : value)),
  }
}

export type Theme = 'dark' | 'light'
const STORAGE_KEY = 'division-ds-theme'

export function getStoredTheme(): Theme {
  try {
    const stored = localStorage.getItem(STORAGE_KEY)
    return stored === 'light' ? 'light' : 'dark'
  } catch {
    return 'dark'
  }
}

export function setTheme(theme: Theme) {
  document.documentElement.setAttribute('data-theme', theme)
  try {
    localStorage.setItem(STORAGE_KEY, theme)
  } catch {
    // per-viewer convenience only -- a private window or blocked storage is fine to lose
  }
}

export function readCssVar(name: string): string {
  return getComputedStyle(document.documentElement).getPropertyValue(name).trim()
}

import { CircleAlert, CircleCheck, Info, TriangleAlert, type LucideIcon } from 'lucide-react'

export type Tone = 'info' | 'ok' | 'warning' | 'hostile'

/** How each status tone shows itself, in one place, for Alert and Toast.
 *
 *  Every tone has an icon and a word as well as a colour, because SC 1.4.1 forbids colour as the
 *  only cue. Colour comes from the `.text` step, the theme-adaptive one gated at 4.5:1 on the
 *  page in both themes, never from `.fill`, which is theme-invariant and fails on the light page.
 *
 *  The class strings are written out in full rather than built from the tone name, because
 *  Tailwind finds classes by scanning source text and cannot see a template literal's result. */
export const TONES: Record<Tone, { icon: LucideIcon; word: string; text: string; border: string }> = {
  info: {
    icon: Info,
    word: 'Information',
    text: 'text-[var(--color-accent-info-text)]',
    border: 'border-[var(--color-accent-info-text)]',
  },
  ok: {
    icon: CircleCheck,
    word: 'Success',
    text: 'text-[var(--color-accent-ok-text)]',
    border: 'border-[var(--color-accent-ok-text)]',
  },
  warning: {
    icon: TriangleAlert,
    word: 'Warning',
    text: 'text-[var(--color-accent-warning-text)]',
    border: 'border-[var(--color-accent-warning-text)]',
  },
  hostile: {
    icon: CircleAlert,
    word: 'Error',
    text: 'text-[var(--color-accent-hostile-text)]',
    border: 'border-[var(--color-accent-hostile-text)]',
  },
}

/**
 * Should an effect run at all?
 *
 * Every effect has a static fallback that the component itself always renders as an
 * alternative — a still frame, a plain block. The effect enhances it; it never replaces
 * content that would otherwise be missing. A "no" here is the same page, still legible and
 * still usable. (This is a client-rendered app — `index.html` ships an empty `#root` — so the
 * fallback exists for a reader who has JS but not motion, not for a reader with no JS at all.)
 */

export function prefersReducedMotion(): boolean {
  return window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false
}

export function prefersSaveData(): boolean {
  const c = (navigator as Navigator & { connection?: { saveData?: boolean } }).connection
  return c?.saveData === true
}

/** `?fx=force` lets a reviewer see effects with OS reduced-motion on. Never overrides save-data. */
function forced(): boolean {
  try {
    return new URLSearchParams(location.search).get('fx') === 'force'
  } catch {
    return false
  }
}

/**
 * A data-saver user's bytes are never spent, even for a reviewer forcing effects —
 * save-data is checked before `?fx=force` and short-circuits it.
 */
export function motionAllowed(reduced = prefersReducedMotion()): boolean {
  if (prefersSaveData()) return false
  if (forced()) return true
  return !reduced
}

export function onReducedMotionChange(fn: (reduced: boolean) => void): () => void {
  if (!window.matchMedia) return () => {}
  const mq = window.matchMedia('(prefers-reduced-motion: reduce)')
  const handler = (e: MediaQueryListEvent) => fn(e.matches)
  mq.addEventListener('change', handler)
  return () => mq.removeEventListener('change', handler)
}

/* Cut-corner shape tokens, ported from the Phase 1 mood board's "cut corners" motif.
   clip-path clips ANYTHING painted on the element it's applied to, including a focus ring drawn
   as its own outline/box-shadow -- so the ring must live on an unclipped wrapper, never on the
   clipped element itself. See ShapeGuideline.tsx's focus demo and BUILD-LOG.md's Phase 2 finding
   (augmented-ui: clip-path can clip a focus ring right off the element). */
.bevel-sm { --bevel-cut: calc(8px * var(--shape-bevel, 1)); }
.bevel-md { --bevel-cut: calc(14px * var(--shape-bevel, 1)); }
.bevel-lg { --bevel-cut: calc(22px * var(--shape-bevel, 1)); }
/* The shape switch (theme builder, docs/improvements/14-theme-shape.md). Two variables a consumer
   may set on :root, neither defined by the system, so the fallbacks are the shipped look:
   `--shape-bevel` scales every cut (1 = the cut corner, 0 = none) and `--shape-radius` rounds the
   corners once the cut is gone. A zero cut makes the polygon the full box, which clips nothing a
   radius draws inside it, and makes `.bevel-edge`'s square zero-sized, so the diagonal disappears
   with the cut. */
.bevel-sm, .bevel-md, .bevel-lg, .bevel-alert {
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - var(--bevel-cut)), calc(100% - var(--bevel-cut)) 100%, 0 100%);
  border-radius: var(--shape-radius, 0px);
}
/* Square corners on a control that is otherwise bevelled: for a control that sits flush against a
   neighbour at its bottom-right, where the cut would open a notch in the shared seam
   (QuantityStepper's Decrease button). Unlayered and after the three above, so it wins over them
   and over Tailwind utilities alike; it also drops the `.bevel-edge` diagonal the cut no longer
   needs. */
.bevel-none { clip-path: none; }
.bevel-none.bevel-edge::after { content: none; }

/* The diagonal edge a bordered bevel is otherwise missing.

   clip-path cuts the corner off the border box, border included, so a bevelled element with a
   1px border shows three bordered sides, a bordered bottom, and a bare diagonal where the cut
   is: the outline visibly breaks at the one corner the shape is known for. This paints the
   missing stretch. It is a square the size of the cut, sat on the border-box corner, filled
   with a gradient whose 50% line IS the cut line (a `to bottom right` gradient in a square puts
   its midline on the other diagonal exactly), coloured from just inside that line outward. The
   element's own clip-path then trims the outer half, leaving a band hugging the cut.

   1.25px rather than 1px: a 45-degree hairline antialiases across two pixel columns and reads
   lighter than the straight 1px sides beside it; the extra quarter pixel brings it back to the
   same visual weight. Set `--bevel-edge-color` to the element's border colour. It assumes a 1px
   border, which is the only border width a bevelled element carries in this system.

   The element must be positioned (`relative` or `absolute`) for the square to anchor to it. This
   rule deliberately does not set `position` itself: it is unlayered, so it would outrank a
   Tailwind `absolute` on the same element and silently pull a backing layer back into flow. */
.bevel-edge::after {
  content: "";
  position: absolute;
  right: -1px;
  bottom: -1px;
  width: var(--bevel-cut, 8px);
  height: var(--bevel-cut, 8px);
  pointer-events: none;
  background: linear-gradient(
    to bottom right,
    transparent calc(50% - 1.25px),
    var(--bevel-edge-color, currentColor) calc(50% - 1.25px)
  );
}

/* ---- Alert: a bottom-right cut sized to the button inside it --------------------------------
   Same corner (bottom-right) and 45 degrees as Button, cut 12px on every Alert, full and compact
   (Victor, 2026-10-14). The Alert's side padding is 8px (`px-2`, set in Alert.tsx), so an action
   Button's own 8px cut sits close enough to the Alert's corner for the two diagonals to read as
   one shape. He chose 12px by eye over the literal "child cut + padding" sum (24px), whose
   diagonal gap read wider than the side gap. Pairs with `.bevel-edge` for the border along the
   diagonal (the Alert sets `--bevel-edge-color` per tone), and the Alert must be `relative`, as
   `.bevel-edge` requires. */
.bevel-alert {
  --bevel-cut: calc(12px * var(--shape-bevel, 1));
}

.bevel-focus-wrap {
  display: inline-block;
  /* Follows a rounded control: the ring sits 3px out, so its radius is 3px larger. min() keeps
     it exactly 0 while the radius is 0, so the shipped square ring is unchanged. */
  border-radius: min(var(--shape-radius, 0px) * 1000, var(--shape-radius, 0px) + 3px);
  outline: 2px solid transparent;
  outline-offset: 3px;
}
/* :has(:focus-visible), not :focus-within. :focus-within matches whenever the inner button holds
   focus, including after a mouse click — so a clicked Button painted a ring while a clicked
   Checkbox (which uses focus-visible: directly, like every unbevelled control here) did not. The
   bevelled/unbevelled split is about WHERE the ring lives, never about WHEN it appears; both
   halves now answer to focus-visible. */
.bevel-focus-wrap:has(:focus-visible) {
  outline-color: var(--color-focus-ring);
}

/* Reticle lock-on: the hover signature of Button and IconButton, from the mood board's
   "Reticle lock-on" motif. Four corner brackets start wide and faint and close onto the control.

   It lives on the unclipped `.bevel-focus-wrap`, for the same reason the focus ring does: the
   control's own clip-path would cut brackets drawn outside its box clean off.

   A transition, not the mood board's looping keyframe. The board animated it forever to show it
   off; on a real control it runs once per hover and holds, and reverses when the pointer leaves.
   Same restraint as M5: nothing re-fires while the pointer rests. It is monotonic (the brackets
   only ever close in and brighten), so, as with M5, WCAG 2.3.1's flash rule has nothing to count.

   Disabled controls do not lock on. `:has(> :hover:not(:disabled):not([aria-disabled="true"]))`
   keys the bracket to the control, not to the wrapper, so the wrapper's own box never triggers it.

   Opt out with `.no-reticle` on the wrapper, for a control nested so tightly inside another
   element (Tag's dismiss button) that brackets outside it would land on its parent's border. */
.bevel-focus-wrap { position: relative; }
.bevel-focus-wrap::before {
  content: "";
  position: absolute;
  inset: calc(-1 * var(--reticle-from, 12px));
  pointer-events: none;
  opacity: 0;
  --reticle-arm: 10px;
  --reticle-c: var(--color-accent-signal-fill);
  background:
    linear-gradient(var(--reticle-c), var(--reticle-c)) 0 0 / var(--reticle-arm) 2px,
    linear-gradient(var(--reticle-c), var(--reticle-c)) 0 0 / 2px var(--reticle-arm),
    linear-gradient(var(--reticle-c), var(--reticle-c)) 100% 0 / var(--reticle-arm) 2px,
    linear-gradient(var(--reticle-c), var(--reticle-c)) 100% 0 / 2px var(--reticle-arm),
    linear-gradient(var(--reticle-c), var(--reticle-c)) 0 100% / var(--reticle-arm) 2px,
    linear-gradient(var(--reticle-c), var(--reticle-c)) 0 100% / 2px var(--reticle-arm),
    linear-gradient(var(--reticle-c), var(--reticle-c)) 100% 100% / var(--reticle-arm) 2px,
    linear-gradient(var(--reticle-c), var(--reticle-c)) 100% 100% / 2px var(--reticle-arm);
  background-repeat: no-repeat;
  /* Leaving: fast and flat, so a pointer sweeping across a toolbar does not leave a trail. */
  transition: inset var(--duration-fast) linear, opacity var(--duration-fast) linear;
}
.bevel-focus-wrap:has(> :hover:not(:disabled):not([aria-disabled="true"]))::before {
  inset: calc(-1 * var(--reticle-to, 5px));
  opacity: 1;
  /* Arriving: the M1 snap curve, over the lock-on window the mood board specifies (160-220ms). */
  transition: inset var(--duration-base) var(--ease-snap), opacity var(--duration-base) var(--ease-snap);
}
.bevel-focus-wrap.no-reticle::before { content: none; }

@media (prefers-reduced-motion: reduce) {
  /* The brackets still appear, which is the information; they just do not travel. */
  .bevel-focus-wrap::before,
  .bevel-focus-wrap:has(> :hover)::before {
    transition: none;
  }
}

/* The colour transition every unbevelled interactive element uses, with `outline-color`
   deliberately left out of the property list.

   Tailwind v4's `transition-colors` expands to
   `color, background-color, border-color, outline-color, text-decoration-color, fill, stroke, …`.
   Every unbevelled control here draws its own focus ring as an `outline` and declares no
   `outline-color` at rest, so the property started at its initial value — `currentColor`, i.e.
   `text.primary`, near-white in the dark theme — and animated to `--color-focus-ring` over the
   whole 120ms. Measured on `main input` at /components/input: rgb(233,238,244) at t+0ms,
   rgb(239,139,96) at t+30ms, rgb(242,85,15) at t+60ms. The ring is this system's reticle motif
   and the one signal a keyboard user relies on; it has to be the right colour at the instant of
   focus, not a tenth of a second later.

   Excluding the property rather than painting a transparent outline at rest: a transparent rest
   colour only converts a wrong-coloured animation into a fade-in, and `.bevel-focus-wrap` has no
   transition at all, so the bevelled half would still paint instantly while the unbevelled half
   arrived over 120ms. design.md's rule is that the bevelled/unbevelled split is about WHERE the
   ring lives and never about WHEN it appears — so the ring is excluded from motion on both
   halves. This matches Button, which has always listed its transitioned properties explicitly.

   Reduced motion is handled here rather than by a `motion-reduce:transition-none` utility at each
   call site: this rule is unlayered, so it outranks Tailwind's layered utilities and a variant
   class could not override it. */
.transition-control {
  transition-property: color, background-color, border-color, text-decoration-color, fill, stroke;
  transition-duration: var(--duration-fast);
  /* Tailwind's own default transition curve, stated explicitly so moving off `transition-colors`
     changes nothing but the property list. */
  transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
}

@media (prefers-reduced-motion: reduce) {
  .transition-control {
    transition-property: none;
  }
}

/* Panel chrome and the corner crosshair, ported from the Phase 1 mood board (G1-decided: dimmed,
   solid colour, symmetric arms of equal length at all four corners). */
.panel {
  position: relative;
  background: var(--color-surface-raised);
  border: 1px solid var(--color-border-hairline);
  backdrop-filter: blur(6px);
  /* The theme builder's shape switch; unset, it is the square panel. See bevel.css. */
  border-radius: var(--shape-radius, 0px);
}

/* The crosshair, split out of `.panel` so a surface can take the motif without also taking the
   panel's fill, border and blur. Select's portalled listbox is the one atom that is a surface
   framing other content, and it brings its own fill and border; before this split it could only
   have had the crosshair by inheriting those too.

   The arms are drawn 5px OUTSIDE the element, so a host must not clip its own overflow. */
.crosshair {
  position: relative;
}
.crosshair::before {
  content: "";
  position: absolute;
  inset: -5px;
  pointer-events: none;
  background:
    linear-gradient(var(--color-text-muted), var(--color-text-muted)) left 1px top 4px/15px 1px no-repeat,
    linear-gradient(var(--color-text-muted), var(--color-text-muted)) left 4px top 1px/1px 14px no-repeat,
    linear-gradient(var(--color-text-muted), var(--color-text-muted)) right 1px top 4px/15px 1px no-repeat,
    linear-gradient(var(--color-text-muted), var(--color-text-muted)) right 4px top 1px/1px 14px no-repeat,
    linear-gradient(var(--color-text-muted), var(--color-text-muted)) left 1px bottom 4px/15px 1px no-repeat,
    linear-gradient(var(--color-text-muted), var(--color-text-muted)) left 4px bottom 1px/1px 14px no-repeat,
    linear-gradient(var(--color-text-muted), var(--color-text-muted)) right 1px bottom 4px/15px 1px no-repeat,
    linear-gradient(var(--color-text-muted), var(--color-text-muted)) right 4px bottom 1px/1px 14px no-repeat;
}

/* Hero tilt: static, blurred glass, reserved for hero/marketing sections only (G1-decided). */
.holo {
  transform: perspective(700px) rotateY(-14deg) rotateX(3deg);
  background: var(--color-surface-raised);
  border: 1px solid var(--color-border-hairline-strong);
  backdrop-filter: blur(10px);
  box-shadow: 0 30px 60px rgba(0, 0, 0, 0.5); /* token-discipline: allow, a cast shadow is black in both themes */
}

/* An interactive card: one whose whole surface is a click target (Card's `interactive` prop sets
   this class; nothing else should). Flat and hairline-bordered at rest. On hover, and while
   anything inside it has keyboard focus, the border takes the signal accent and the whole card
   slides up 4px.

   `:has(:focus-visible)`, not `:focus-within`, so a keyboard user gets it and a card does not
   stay lit and raised after a mouse click on a button inside it.

   `transform` is set only in the hover state. At rest the card has no transform at all: no
   stacking context, no compositor layer, text drawn on the pixel grid. It is a transform, so no
   layout box moves. The crosshair marks and a CardMedia are inside the card and travel with it.
   Border and lift ease over `--duration-base` (180ms) `ease-out`, the same as the border did.

   There is no glow shadow: the hover is the border and the lift, nothing else. To bring the
   glow back, add `box-shadow: 0 0 20px -4px var(--color-accent-signal-glow);` to the hover rule
   and `box-shadow` to the transition-property. */
.card-interactive {
  transition-property: border-color, transform;
  transition-duration: var(--duration-base);
  transition-timing-function: ease-out;
}
.card-interactive:hover,
.card-interactive:has(:focus-visible) {
  border-color: var(--color-accent-signal-indicator);
  transform: translateY(-4px);
}
@media (prefers-reduced-motion: reduce) {
  /* The border still changes, at once. The card does not move. */
  .card-interactive {
    transition: none;
  }
  .card-interactive:hover,
  .card-interactive:has(:focus-visible) {
    transform: none;
  }
}

/* M1 snap-in: elements arrive a little large and settle. Signature motion for focus/selection/toasts. */
@keyframes snap-in {
  from { opacity: 0; transform: scale(1.08); }
  to { opacity: 1; transform: scale(1); }
}
.anim-snap-in { animation: snap-in var(--duration-base) var(--ease-snap); }

/* M2 draw-on line: a hairline scales in from one edge before content settles. */
@keyframes draw-on {
  from { transform: scaleX(0); }
  to { transform: scaleX(1); }
}
.anim-draw-on { transform-origin: left; animation: draw-on var(--duration-slow) var(--ease-snap); }

/* M4 rationed glitch: capped at 2 iterations of a 400ms cycle (~2.5 flashes/sec), staying under
   the WCAG 2.3.1 limit of 3 flashes per second. Errors and "signal lost" moments only. */
@keyframes glitch-flash {
  0%, 100% { filter: none; transform: translateX(0); }
  50% { filter: hue-rotate(25deg); transform: translateX(1px); }
}
.anim-glitch { animation: glitch-flash 400ms steps(2) 2; }

/* M5 stepped arrival: the hover state lands in discrete jumps instead of sliding in.

   A transition with a stepped timing function, deliberately NOT a keyframe animation and
   deliberately NOT `.anim-glitch` above, for three reasons in order of how load-bearing they are:

   1. Restraint. PRODUCT.md Principle 3 reserves the glitch for failure. Hover is the
      highest-frequency interaction in the system, so spending the one effect that carries meaning
      on it leaves nothing left to say "this broke". The discrete, switched quality is the part
      worth having here; the hue shift and the jitter are the part that has to stay rare.
   2. The rule enforces itself. A transition fires once per state entry by construction: there is
      no iteration count to cap and nothing can re-fire while the pointer rests, so "it must not
      repeat" stops being a thing to police. It also reverses on pointer-leave with no second
      keyframe.
   3. It reads as a switching circuit rather than as a tween, which is the whole point.

   FLASH SAFETY, and read this before changing the step count or the duration. WCAG 2.3.1 counts a
   flash as a PAIR of opposing changes in relative luminance. This staircase is monotonic: every
   step moves further toward the hover value and never back, so it contains no opposing change and
   is not a flash at any step rate. That is why there is no three-per-second cap here, and why the
   absence of one is a conclusion rather than an oversight. `.anim-glitch` needs its cap because
   its cycle returns to where it started. If anyone ever adds an over- or under-shoot to this
   staircase, 2.3.1 applies again and the rate has to be measured and written down the way M4's
   comment does it. Do not copy the absence of a cap out of here into something non-monotonic.

   Cadence. 3 steps over 180ms is a 60ms plateau each, chosen by sampling the rendered `filter`
   and `background-color` once per animation frame rather than by picking a number. Measured on
   Button variant=danger, headless Chromium at 60fps, each plateau given as the span of frames
   holding one value: 180ms x 3 holds for 5, 4 and then indefinitely (the chosen one, each step
   clearly its own state); 120ms x 3, the old `--duration-fast`, holds for 4 then 2 frames, which
   reads as a cheap ramp; 160ms x 3 holds 5 then 3; 200ms x 3 matches 180ms frame for frame and
   only costs 20ms; 180ms x 2 gives a single mid-tone, closer to a crossfade than to switching;
   180ms x 6 holds each of the five intermediates for 1 to 2 frames, which is indistinguishable
   from smooth and also below the resolution any test could see. 240ms x 4 also reads well but
   240ms is long for the highest-frequency interaction in the system.

   The step count lives in `--steps-arrival` so the cadence is readable from one place, and
   `e2e/button-hover.spec.ts` reads it back off the computed timing function instead of hardcoding
   a number, then asserts the plateau is at least 50ms so a future 6-step version fails the gate
   rather than quietly becoming a ramp again.

   Press stays instant. `:active` zeroes the duration, so a press acknowledges in the frame it
   happens: measured `brightness(0.95)` on the first frame after `mousedown`, one distinct value
   for the whole press. Stepping is for arrival, not for acknowledgement, and a press that climbs
   a staircase reads as lag. This was NOT already true and is a fix rather than a preservation:
   before M5, `active:brightness-95` rode the same 120ms hover transition as everything else on
   Button, so the press ramped too.

   Reduced motion is handled inside this rule rather than by a `motion-reduce:transition-none`
   utility at the call site, because this rule is unlayered and therefore outranks Tailwind's
   layered utilities: a variant class at the call site could not override it. Same decision and
   the same reason as `.transition-control` in control.css.

   What that collapse does and does not compute to, because it is easy to assert the wrong thing:
   `transition-property` becomes `none`, and `transition-duration` stays at its declared 180ms.
   Tailwind's own `transition-none` behaves identically (`transition-property: none`, nothing
   else), so this was already the case before M5. A gate written as "duration computes to 0s"
   would have been red against working code. The observable claim, and the one
   `e2e/button-hover.spec.ts` makes, is that the settled hover value is already in place on the
   first frame after the pointer arrives, with no intermediate value at all. */
.transition-stepped {
  --steps-arrival: 3;
  transition-property: background-color, color, border-color, filter;
  transition-duration: var(--duration-stepped);
  /* `jump-start`, not the `jump-end` default: the first step lands in the frame the pointer
     arrives, so the control answers immediately and then climbs. `jump-end` holds the rest value
     for the first 60ms, which reads as lag on an interaction that has to feel instant. */
  transition-timing-function: steps(var(--steps-arrival), jump-start);
}

.transition-stepped:active {
  transition-duration: 0s;
}

@media (prefers-reduced-motion: reduce) {
  .transition-stepped {
    transition-property: none;
  }
}

/* Spinner, ring variant. Two motions at different periods (a 2s turn and a 1.5s arc that grows
   then slides away), so the arc never lands in the same place twice in a row and reads as working
   rather than as a wheel. Circumference at r=9.5 is ~59.7, hence the 59.7 offset at the end: the
   arc slides fully off before the next one grows. Ported from the dash-ring reference Victor
   supplied, moved from SMIL into CSS so reduced motion can stop it. */
@keyframes spinner-turn { to { transform: rotate(360deg); } }
@keyframes spinner-arc {
  0% { stroke-dasharray: 0 150; stroke-dashoffset: 0; }
  50% { stroke-dasharray: 42 150; stroke-dashoffset: -16; }
  100% { stroke-dasharray: 42 150; stroke-dashoffset: -59.7; }
}
.spinner-ring { transform-origin: center; animation: spinner-turn 2s linear infinite; }
.spinner-ring-arc { stroke-dasharray: 42 150; animation: spinner-arc 1.5s ease-in-out infinite; }

/* Spinner, conveyor variant. Each block runs the whole track, the trailing shades a beat behind
   the lead block, so the three travel as one smeared shape. */
@keyframes spinner-conveyor {
  from { transform: translateX(var(--conveyor-start)); }
  to { transform: translateX(var(--conveyor-end)); }
}
/* The numbers below assume the component's 10-column track and 3 blocks: the blocks travel from
   -2ch to 12ch (14ch) in 1.8s, so each 0.05s of lag is 0.39ch.

   The track under the blocks is hidden by a moving mask rather than by painting the blocks in
   the page colour, so the spinner works on any surface. The mask image is 30ch wide, opaque
   except for a window at 13.1ch to 15ch: the lead block's width plus the two trailing blocks'
   0.78ch of lag. The mask slides on the lead block's exact clock, from -16ch to -2ch, which
   keeps the window's right edge on the lead block's right edge the whole way across. */
@keyframes spinner-conveyor-window {
  from { mask-position: -16ch 0; }
  to { mask-position: -2ch 0; }
}
.spinner-conveyor-track {
  /* token-discipline: allow, a mask reads alpha only, so its black is never painted */
  mask-image: linear-gradient(to right, #000 13.1ch, transparent 13.1ch, transparent 15ch, #000 15ch);
  mask-size: 30ch 100%;
  mask-repeat: no-repeat;
  animation: spinner-conveyor-window 1.8s linear infinite;
}
.spinner-conveyor-block {
  animation: spinner-conveyor 1.8s linear infinite;
  animation-delay: calc(0.05s * var(--i));
}

@media (prefers-reduced-motion: reduce) {
  /* Stopped, not removed: the ring holds a three-quarter arc and the conveyor holds its blocks
     mid-track, so a still spinner still looks like a spinner. The label carries the meaning. */
  .spinner-ring,
  .spinner-ring-arc {
    animation: none;
  }
  .spinner-conveyor-block {
    animation-play-state: paused;
    animation-delay: calc(-0.7s + 0.05s * var(--i));
  }
  .spinner-conveyor-track {
    animation-play-state: paused;
    animation-delay: -0.7s;
  }
}

@media (prefers-reduced-motion: reduce) {
  .anim-snap-in,
  .anim-draw-on,
  .anim-glitch {
    animation: none !important;
  }
}

/* Docs route change. The routed view inside #main arrives in a short cascade: the page header
   first, then each following block 40ms behind the one before (capped at 5 steps, 200ms of
   stagger, the same cap and step the Sidebar organism's group reveal uses). Each block fades and
   rises 8px over --duration-slow on --ease-snap. Only the routed view animates: the header and
   sidebar sit outside it and never re-render, so nothing around the content moves.

   Applied only after an in-app navigation (AppShell keys it off `location.key`), never on a fresh
   load: a direct load has nothing to transition from, and the axe sweeps that load a page directly
   must never sample a mid-fade frame. `both` fill holds the delayed blocks at their start frame,
   so a block waiting its turn is invisible rather than drawn and then snapped back to hidden. */
@keyframes route-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}
.anim-route-in > * > * {
  animation: route-in var(--duration-slow) var(--ease-snap) both;
}
.anim-route-in > * > :nth-child(2) { animation-delay: 40ms; }
.anim-route-in > * > :nth-child(3) { animation-delay: 80ms; }
.anim-route-in > * > :nth-child(4) { animation-delay: 120ms; }
.anim-route-in > * > :nth-child(5) { animation-delay: 160ms; }
.anim-route-in > * > :nth-child(n + 6) { animation-delay: 200ms; }

@media (prefers-reduced-motion: reduce) {
  .anim-route-in > * > * {
    animation: none !important;
  }
}

/* M7 exits. Every surface that leaves the screen leaves with a motion of its own, chosen by what
   it is, never one fade for everything:

   - A popup menu (`.anim-popover`) slides down out of its trigger to open and back up into it to
     close, so it reads as attached to the thing that opened it. Opened above its trigger
     (`data-side="top"`), both directions flip.
   - An overlay surface (`.anim-overlay`) settles in with M1 and shrinks slightly as it fades out;
     its scrim (`.anim-scrim`) fades with it. A Sheet (`data-side` left or right) slides back off
     its own edge instead.
   - A Tag or an Alert is removed by JavaScript (`src/lib/exit.ts`), because what happens after the
     fade is layout: the Tag's neighbours slide over into its place, the Alert's height collapses.

   Exits run on `--ease-accelerate` at `--duration-fast`: leaving is quicker than arriving, and an
   ease-in reads as the thing moving away rather than settling. Radix's Presence keeps a closed
   menu, dialog or sheet mounted until its exit animation ends, and unmounts at once when the
   animation is `none`, which is what reduced motion sets below. */
@keyframes popover-down-in { from { opacity: 0; transform: translateY(-8px); } }
@keyframes popover-up-out { to { opacity: 0; transform: translateY(-8px); } }
@keyframes popover-up-in { from { opacity: 0; transform: translateY(8px); } }
@keyframes popover-down-out { to { opacity: 0; transform: translateY(8px); } }
.anim-popover { animation: popover-down-in var(--duration-base) var(--ease-snap); }
.anim-popover[data-side="top"] { animation-name: popover-up-in; }
.anim-popover[data-state="closed"] {
  animation: popover-up-out var(--duration-fast) var(--ease-accelerate) forwards;
}
.anim-popover[data-side="top"][data-state="closed"] { animation-name: popover-down-out; }

@keyframes overlay-out { to { opacity: 0; transform: scale(0.96); } }
@keyframes sheet-out-right { to { transform: translateX(100%); } }
@keyframes sheet-out-left { to { transform: translateX(-100%); } }
@keyframes scrim-in { from { opacity: 0; } }
@keyframes scrim-out { to { opacity: 0; } }
.anim-overlay { animation: snap-in var(--duration-base) var(--ease-snap); }
.anim-overlay[data-state="closed"] {
  animation: overlay-out var(--duration-fast) var(--ease-accelerate) forwards;
}
.anim-overlay[data-side="right"][data-state="closed"] {
  animation: sheet-out-right var(--duration-base) var(--ease-accelerate) forwards;
}
.anim-overlay[data-side="left"][data-state="closed"] {
  animation: sheet-out-left var(--duration-base) var(--ease-accelerate) forwards;
}
/* The scrim outlasts the surface it holds: Presence unmounts the scrim, and the surface with it,
   when the scrim's own animation ends, so it must never end first. */
.anim-scrim { animation: scrim-in var(--duration-base) var(--ease-snap); }
.anim-scrim[data-state="closed"] {
  animation: scrim-out var(--duration-base) var(--ease-accelerate) forwards;
}

@media (prefers-reduced-motion: reduce) {
  .anim-popover,
  .anim-overlay,
  .anim-scrim {
    animation: none !important;
  }
}

/* ---- Accordion height (added 2026-10-14) ----
   An Accordion panel opens by growing from 0 to the height Radix measures for it and publishes as
   `--radix-accordion-content-height`, and closes by shrinking back on the SAME clock (see the close
   rule): both on `--duration-base`/`--ease-snap`, so single mode blends old total to new total.
   The opacity rides along so the text does not sit fully
   inked against a clip edge that is still moving.

   `forwards` on the close holds the 0 height until Presence unmounts the panel, so there is no
   frame at full height between the animation ending and the panel leaving. Radix suppresses the
   open animation on first mount, so an item open by default renders open, not growing.

   Height, not a transform: the content below has to move with the panel, and only a layout
   property moves it. The panels are short and the animation is 120 to 180ms, so the layout cost is
   a handful of frames on one subtree. */
@keyframes accordion-open {
  from { height: 0; opacity: 0; }
  to { height: var(--radix-accordion-content-height); opacity: 1; }
}
@keyframes accordion-close {
  from { height: var(--radix-accordion-content-height); opacity: 1; }
  to { height: 0; opacity: 0; }
}
.anim-accordion[data-state="open"] {
  animation: accordion-open var(--duration-base) var(--ease-snap);
}
.anim-accordion[data-state="closed"] {
  /* Same duration and curve as the open, on purpose: in single mode one panel closes while its
     neighbour opens, and the root's height is the sum of the two. Matching clocks make that sum a
     straight blend of old total to new total; a quicker, differently eased close made it
     overshoot (the block below jumped down, then back up). */
  animation: accordion-close var(--duration-base) var(--ease-snap) forwards;
}

@media (prefers-reduced-motion: reduce) {
  /* `none` makes Presence unmount a closing panel at once, so the panel snaps shut. */
  .anim-accordion {
    animation: none !important;
  }
}
/* ---- end Accordion height ---- */

/* Skeleton sweep (added 2026-10-14). A loading placeholder (src/components/atoms/skeleton) paints
   a translucent hairline fill, and a slightly brighter band crosses it left to right, once every
   1.6s. Both colours are border tokens because both are translucent: the same placeholder reads on
   the page, on a raised Card and inside an overlay without a per-surface variant.

   A sweep and not a pulse: a pulse fades the whole shape up and down, which is a repeated
   opposing luminance change across the full area. The sweep moves a soft band over a fixed fill,
   so no area flashes, and its contrast is that of two hairline tokens, far under WCAG 2.3.1's
   threshold at any rate. `linear`, because a scanner does not ease.

   Reduced motion removes the band as well as stopping it: a band frozen mid-shape reads as a
   highlight that means something. The shape keeps its flat fill, which is still a placeholder.

   The band is a fixed 320px, not a percentage of the shape. Sized to the shape, a 36px avatar
   placeholder got a 36px band and read as a shaded cylinder; at a fixed width a small shape is
   washed evenly as the band passes, and a wide one sees a band of the same softness as a narrow
   one. The positions run from one band-width off the left edge to one band-width off the right. */
@keyframes skeleton-sweep {
  from { background-position: -320px 0; }
  to { background-position: calc(100% + 320px) 0; }
}
.skeleton-shimmer {
  background-color: var(--color-border-hairline);
  background-image: linear-gradient(
    90deg,
    transparent 0%,
    var(--color-border-hairline-strong) 50%,
    transparent 100%
  );
  background-size: 320px 100%;
  background-repeat: no-repeat;
  animation: skeleton-sweep 1.6s linear infinite;
}

@media (prefers-reduced-motion: reduce) {
  .skeleton-shimmer {
    animation: none !important;
    background-image: none;
  }
}

/* ---- Tabs indicator ----
   One block per tab list, slid under the active trigger (Tabs.tsx measures it). Transitions are
   off until `data-ready`, so the first paint lands in place; reduced motion jumps. */
.tabs-indicator { transition: none; }
.tabs-indicator[data-ready] {
  transition:
    transform var(--duration-base) var(--ease-snap),
    width var(--duration-base) var(--ease-snap),
    height var(--duration-base) var(--ease-snap);
}
@media (prefers-reduced-motion: reduce) {
  .tabs-indicator[data-ready] { transition: none; }
}

/* ---- Tooltip entry (added 2026-10-14) ----
   Opacity only, no scale. A tooltip is a 1px-bordered, cut-corner (clip-path) surface sitting on a
   fractional pixel position. M1's scale(1.08) put the clip edge and the border on sub-pixel rows
   for the whole animation, and the bottom border row, the one the clip-path trims, dropped out
   until the transform settled: the outline arrived in two steps. A fade keeps every edge on the
   pixel grid, so the outline and the fill appear together. */
@keyframes tooltip-in { from { opacity: 0; } to { opacity: 1; } }
.anim-tooltip { animation: tooltip-in var(--duration-fast) var(--ease-snap); }
@media (prefers-reduced-motion: reduce) {
  .anim-tooltip { animation: none !important; }
}
/* ---- end Tooltip entry ---- */

/* Scrollbars, drawn from the system's own tokens instead of the OS default: a grey rounded
   Windows bar in a near-black, square-cornered UI was the one surface on every page that the
   token pipeline never reached.

   The thumb rests at `border.control`, the same grey every unbevelled control's outline uses, so
   it reads as a control and not as decoration. It warms to `accent.signal.fill` only while it is
   being hovered or dragged, the same "the accent means you are touching this" rule the sidebar's
   current item follows. The track is transparent so the column behind it (`surface.base`) shows
   through. Square ends, never rounded: the system has no radius outside its bevels.

   Two engines, two syntaxes, and they must not both apply. Chromium 121+ honours the standard
   `scrollbar-color` / `scrollbar-width` and, once either is set, IGNORES every `::-webkit-scrollbar`
   rule. The webkit pseudo-elements are the only way to get a hover colour and an exact width, so
   the standard properties are applied only where the pseudo-elements do not exist (Firefox). */

@supports not selector(::-webkit-scrollbar) {
  * {
    scrollbar-color: var(--color-border-control) transparent;
    scrollbar-width: thin;
  }
}

::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

::-webkit-scrollbar-track,
::-webkit-scrollbar-corner {
  background: transparent;
}

/* The transparent border plus `background-clip: padding-box` draws a 4px bar centred in a 10px
   hit area: thin to look at, still easy to grab. */
::-webkit-scrollbar-thumb {
  background-color: var(--color-border-control);
  background-clip: padding-box;
  border: 3px solid transparent;
  border-radius: 0;
}

::-webkit-scrollbar-thumb:hover,
::-webkit-scrollbar-thumb:active {
  background-color: var(--color-accent-signal-fill);
}

::-webkit-scrollbar-button {
  display: none;
}

